#include <stdio.h>
#include <stddef.h>
#include <stdint.h>

typedef uint64_t u64;
typedef uint32_t u32;
typedef uint16_t u16;
typedef uint8_t u8;
typedef uint64_t __le64;
typedef uint32_t __le32;
typedef uint16_t __le16;

struct bkey_i {
    u64 data[0];
};

struct jset_entry {
    u16     u64s;
    u8      btree_id;
    u8      level;
    u8      type;
    u8      pad[3];
    struct bkey_i       start[0];
    u64         _data[];
};

struct jset_entry_dev_usage_type {
    __le64          buckets;
    __le64          sectors;
    __le64          fragmented;
} __attribute__((packed));

struct jset_entry_dev_usage {
    struct jset_entry   entry;
    __le32          dev;
    __u32           pad;

    __le64          _buckets_ec;        /* No longer used */
    __le64          _buckets_unavailable;   /* No longer used */

    struct jset_entry_dev_usage_type d[];
};

#define vstruct_bytes(_s)   (offsetof(struct jset_entry, _data) + (_s)->u64s * sizeof(u64))

static inline unsigned jset_entry_dev_usage_nr_types(struct jset_entry_dev_usage *u)
{
    return (vstruct_bytes(&u->entry) - sizeof(struct jset_entry_dev_usage)) /
        sizeof(struct jset_entry_dev_usage_type);
}

int main() {
    struct jset_entry_dev_usage u;
    u.entry.u64s = 0; // Smallest possible u64s

    printf("sizeof(struct jset_entry_dev_usage) = %zu\n", sizeof(struct jset_entry_dev_usage));
    printf("sizeof(struct jset_entry_dev_usage_type) = %zu\n", sizeof(struct jset_entry_dev_usage_type));
    printf("vstruct_bytes = %zu\n", vstruct_bytes(&u.entry));

    unsigned nr = jset_entry_dev_usage_nr_types(&u);
    printf("nr_types = %u\n", nr);

    if (nr > 1000) {
        printf("Huge nr_types detected!\n");
    }
    return 0;
}

static inline unsigned jset_entry_dev_usage_nr_types(struct jset_entry_dev_usage *u)
{
	size_t bytes = vstruct_bytes(&u->entry);

	if (bytes < sizeof(struct jset_entry_dev_usage))
		return 0;

	return (bytes - sizeof(struct jset_entry_dev_usage)) /
		sizeof(struct jset_entry_dev_usage_type);
}

